	if problems := reviewTriageRecordProblems(files, read, terminal); len(problems) != 0 {
		t.Fatalf("実在するノードで問題が出た: %v", problems)
	}

	// 形は合うが判定フローに無いノードは報告される。
	bogus := strings.Replace(validRecordYAML, "verdict_node: JNA2", "verdict_node: JNA9", 1)
	bogus = strings.Replace(bogus, "verdict: adopted", "verdict: adopted", 1)
	files, read = recordFiles(t, bogus)
	found := false
	for _, p := range reviewTriageRecordProblems(files, read, terminal) {
		if strings.Contains(p, "JNA9") && strings.Contains(p, "判定フローの決着ノード") {
			found = true
		}
	}
	if !found {
		t.Errorf("判定フローに無いノードが報告されない (%s)", yamlPath)
	}

	// 照合先が読めないとき (nil) は照合しない。スキルを入れずに記録だけ
	// 検査する使い方を残すため。
	files, read = recordFiles(t, bogus)
	for _, p := range reviewTriageRecordProblems(files, read, nil) {
		if strings.Contains(p, "判定フローの決着ノード") {
			t.Errorf("照合先が無いのに照合している: %s", p)
		}
	}
}

